function u_s_out = mfun_ovhz_flux_torque_controller(ref, fbk_in, p)
%MFUN_OVHZ_FLUX_TORQUE_CONTROLLER Block FluxTorqueController of the control system.
%   FluxTorqueController of motulator. Generated by motulator_export from the MATLAB
%   port of motulator and called by the MATLAB Function block of the library of
%   motulator, whose folder motulator.setup adds to the MATLAB path. The parameters are
%   the fields of the struct p (from the mask, [] as NaN). The state is in persistent
%   variables, of which each MATLAB Function block has its own copy.
persistent self
if isempty(self)
    % Machine model (InductionMachineInvGammaPars)
    par = struct('n_p', p.par_n_p, 'R_s', p.par_R_s, 'R_R', p.par_R_R, ...
        'L_sgm', p.par_L_sgm, 'L_M', p.par_L_M);
    self = im_flux_torque_ctrl_init(par, p.alpha_psi, p.alpha_tau);
end
fbk = im_observer_outputs_unpack(fbk_in);
u_s = im_flux_torque_ctrl_compute_output(self, ref(1), ref(2), fbk);
u_s_out = complex_out(u_s);
end

function s = im_observer_outputs_unpack(u)
%IM_OBSERVER_OUTPUTS_UNPACK Struct of the signal vector u.
s = struct( ...
    'i_s', complex(u(1), u(2)), ...
    'u_s', complex(u(3), u(4)), ...
    'u_s_zoh', complex(u(5), u(6)), ...
    'psi_s', complex(u(7), u(8)), ...
    'psi_R', complex(u(9), u(10)), ...
    'tau_M', u(11), ...
    'w_c', u(12), ...
    'w_s', u(13), ...
    'w_r', u(14), ...
    'w_m', u(15), ...
    'w_M', u(16), ...
    'theta_c', u(17), ...
    'e_o', complex(u(18), u(19)), ...
    'eps', u(20), ...
    'h', u(21));
end

function y = complex_out(z)
%COMPLEX_OUT Signal [real part; imaginary part] of a complex number.
y = [real(z); imag(z)];
end

function self = im_flux_torque_ctrl_init(par, alpha_psi, alpha_tau)
%IM_FLUX_TORQUE_CTRL_INIT Flux and torque controller (FluxTorqueController) without
%   the integral action.
self = struct('par', par, 'alpha_psi', alpha_psi, 'alpha_tau', alpha_tau);
end

function u_s_ref = im_flux_torque_ctrl_compute_output(self, psi_s_ref, tau_M_ref, fbk)
%IM_FLUX_TORQUE_CTRL_COMPUTE_OUTPUT Stator voltage reference from the flux and
%   torque references.
par = self.par;
% Auxiliary current, torque-production factor, and directions
t_psi = complex(1);
t_tau = complex(0);
if par.L_sgm > 0 % L_sgm = 0 in open-loop V/Hz control
    i_a = fbk.psi_R/par.L_sgm;
    c_tau = 1.5*par.n_p*real(i_a*conj(fbk.psi_s));
    if c_tau > 0
        t_psi = 1.5*par.n_p*abs(fbk.psi_s)*i_a/c_tau;
        t_tau = 1i*fbk.psi_s/c_tau;
    end
end
% Error signals (the integral action is not used: alpha_i = 0)
e_psi = psi_s_ref - abs(fbk.psi_s);
e_tau = tau_M_ref - fbk.tau_M;
e_u = self.alpha_psi*e_psi*t_psi + self.alpha_tau*e_tau*t_tau;
% Voltage reference
v = par.R_s*fbk.i_s + 1i*fbk.w_s*fbk.psi_s;
u_s_ref = v + e_u;
end
